"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { generateQR } from "@/lib/brasa/utils/qrcode";

export type PixPaymentStatus =
  | "idle"
  | "qr_generated"
  | "waiting_payment"
  | "paid"
  | "expired"
  | "failed";

/**
 * UI-only Pix payment component. Does NOT process payments.
 *
 * The consumer is responsible for:
 * 1. Generating the EMV/BRCode payload on their backend (via their PSP)
 * 2. Passing it as `pixCode` (or a pre-rendered QR image via `qrCodeUrl`)
 * 3. Polling their backend for payment confirmation and updating `status`
 *
 * When no `pixCode` is provided, a placeholder QR is shown with a demo label.
 */
export interface PixPaymentProps {
  /** Payment amount in BRL (e.g. 149.90) */
  amount: number;
  /**
   * Pix copia e cola payload (EMV/BRCode format).
   * Must be generated by your payment backend (PSP).
   * When omitted, a demo placeholder is displayed.
   */
  pixCode?: string;
  /** Pre-rendered QR code image URL — bypasses client-side generation */
  qrCodeUrl?: string;
  /** Expiration time in seconds (default 300) */
  expiresIn?: number;
  /** Beneficiary display name */
  beneficiary?: string;
  /** Called when the user copies the Pix code */
  onCopy?: () => void;
  /** Called when the payment is confirmed (consumer provides polling logic) */
  onPayment?: () => void;
  /** Called when the QR code expires */
  onExpired?: () => void;
  /** Controlled status */
  status?: PixPaymentStatus;
  className?: string;
}

function formatBRL(value: number): string {
  return value.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function formatTime(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${s.toString().padStart(2, "0")}`;
}

function QRCodeSVG({ data, size = 200 }: { data: string; size?: number }) {
  const qr = useMemo(() => {
    try {
      return generateQR(data);
    } catch {
      return null;
    }
  }, [data]);

  if (!qr) return null;

  const cellSize = size / (qr.size + 8);
  const offset = cellSize * 4;

  return (
    <svg viewBox={`0 0 ${size} ${size}`} width={size} height={size} className="block">
      <rect width={size} height={size} fill="white" rx={8} />
      {qr.matrix.map((row, r) =>
        row.map((cell, c) =>
          cell ? (
            <rect
              key={`${r}-${c}`}
              x={offset + c * cellSize}
              y={offset + r * cellSize}
              width={cellSize + 0.5}
              height={cellSize + 0.5}
              fill="#171717"
            />
          ) : null
        )
      )}
      {/* Pix icon overlay */}
      <g transform={`translate(${size / 2}, ${size / 2})`}>
        <rect x={-16} y={-16} width={32} height={32} rx={6} fill="white" />
        <rect x={-13} y={-13} width={26} height={26} rx={4} fill="#32BCAD" />
        <path
          d="M-3.5 -5.5L0 -2L3.5 -5.5M3.5 -5.5L7 -2L3.5 1.5M3.5 1.5L0 5L-3.5 1.5M-3.5 1.5L-7 -2L-3.5 -5.5"
          stroke="white"
          strokeWidth={1.8}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </g>
    </svg>
  );
}

const DEMO_PIX_CODE = "00020126580014br.gov.bcb.pix0136demo-brasa-ui-placeholder5204000053039865802BR";

export function PixPayment({
  amount,
  pixCode,
  qrCodeUrl,
  expiresIn = 300,
  beneficiary,
  onCopy,
  onPayment,
  onExpired,
  status: controlledStatus,
  className = "",
}: PixPaymentProps) {
  const isDemo = !pixCode && !qrCodeUrl;
  const effectivePixCode = pixCode || DEMO_PIX_CODE;

  const [internalStatus, setInternalStatus] = useState<PixPaymentStatus>("qr_generated");
  const [timeLeft, setTimeLeft] = useState(expiresIn);
  const [copied, setCopied] = useState(false);

  const status = controlledStatus ?? internalStatus;

  useEffect(() => {
    if (status !== "qr_generated" && status !== "waiting_payment") return;
    if (timeLeft <= 0) {
      setInternalStatus("expired");
      onExpired?.();
      return;
    }
    const timer = setInterval(() => setTimeLeft((t) => t - 1), 1000);
    return () => clearInterval(timer);
  }, [status, timeLeft, onExpired]);

  const handleCopy = useCallback(() => {
    navigator.clipboard.writeText(effectivePixCode);
    setCopied(true);
    setInternalStatus("waiting_payment");
    onCopy?.();
    setTimeout(() => setCopied(false), 2000);
  }, [effectivePixCode, onCopy]);

  const timerColor =
    timeLeft > 120 ? "text-emerald-600" : timeLeft > 30 ? "text-amber-600" : "text-red-600";
  const timerBg =
    timeLeft > 120 ? "bg-emerald-50" : timeLeft > 30 ? "bg-amber-50" : "bg-red-50";

  if (status === "paid") {
    return (
      <div className={`rounded-2xl border border-emerald-200 bg-gradient-to-b from-emerald-50 to-white p-8 text-center ${className}`}>
        <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-full bg-emerald-100 ring-4 ring-emerald-50">
          <svg className="h-7 w-7 text-emerald-600" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
          </svg>
        </div>
        <p className="text-lg font-bold text-emerald-900">Pagamento confirmado</p>
        <p className="mt-1 text-sm font-medium text-emerald-700">{formatBRL(amount)}</p>
        {beneficiary && <p className="mt-0.5 text-xs text-emerald-600/70">para {beneficiary}</p>}
      </div>
    );
  }

  if (status === "expired") {
    return (
      <div className={`rounded-2xl border border-neutral-200 bg-gradient-to-b from-neutral-50 to-white p-8 text-center ${className}`}>
        <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-full bg-neutral-100">
          <svg className="h-7 w-7 text-neutral-400" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
        </div>
        <p className="text-lg font-bold text-neutral-900">QR Code expirado</p>
        <p className="mt-1 text-sm text-neutral-500">Gere um novo código para continuar</p>
      </div>
    );
  }

  if (status === "failed") {
    return (
      <div className={`rounded-2xl border border-red-200 bg-gradient-to-b from-red-50 to-white p-8 text-center ${className}`}>
        <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-full bg-red-100">
          <svg className="h-7 w-7 text-red-600" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z" />
          </svg>
        </div>
        <p className="text-lg font-bold text-neutral-900">Erro no pagamento</p>
        <p className="mt-1 text-sm text-neutral-500">Tente novamente ou use outro método</p>
      </div>
    );
  }

  return (
    <div className={`overflow-hidden rounded-2xl border border-neutral-200 bg-white shadow-sm ${className}`}>
      {/* Header */}
      <div className="border-b border-neutral-100 bg-gradient-to-r from-neutral-50 to-white px-6 py-4">
        <div className="flex items-center gap-3">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#32BCAD]">
            <svg viewBox="0 0 24 24" className="h-4 w-4 text-white" fill="none" stroke="currentColor" strokeWidth={2.2}>
              <path d="M7 10l3-3 3 3M13 10l3-3 3 3M13 14l3 3 3-3M7 14l3 3 3-3" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </div>
          <div>
            <p className="text-xs font-medium uppercase tracking-wider text-neutral-400">Pagar com Pix</p>
            <p className="text-xl font-bold tracking-tight text-neutral-900">{formatBRL(amount)}</p>
          </div>
        </div>
        {beneficiary && (
          <p className="mt-1 pl-11 text-xs text-neutral-500">para {beneficiary}</p>
        )}
      </div>

      {/* QR Code */}
      <div className="flex flex-col items-center px-6 py-6">
        <div className="relative rounded-xl border border-neutral-100 bg-white p-2 shadow-sm">
          {qrCodeUrl ? (
            <img
              src={qrCodeUrl}
              alt="QR Code Pix"
              width={180}
              height={180}
              className="block rounded-lg"
            />
          ) : (
            <QRCodeSVG data={effectivePixCode} size={180} />
          )}
          {isDemo && (
            <div className="absolute -top-2 -right-2 rounded-full bg-amber-500 px-2 py-0.5 text-[10px] font-bold text-white shadow-sm">
              DEMO
            </div>
          )}
        </div>

        {/* Timer */}
        <div className={`mt-4 inline-flex items-center gap-1.5 rounded-full px-3 py-1 ${timerBg}`}>
          <svg className={`h-3.5 w-3.5 ${timerColor}`} fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          <span className={`font-mono text-xs font-semibold ${timerColor}`}>
            {formatTime(timeLeft)}
          </span>
        </div>
      </div>

      {/* Copy button */}
      <div className="border-t border-neutral-100 px-6 py-4">
        <button
          type="button"
          onClick={handleCopy}
          className={`flex w-full items-center justify-center gap-2 rounded-xl px-4 py-3 text-sm font-semibold transition-all ${
            copied
              ? "bg-emerald-600 text-white"
              : "bg-neutral-900 text-white hover:bg-neutral-800 active:scale-[0.98]"
          }`}
        >
          {copied ? (
            <>
              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
              </svg>
              Código copiado!
            </>
          ) : (
            <>
              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" d="M8.25 7.5V6.108c0-1.135.845-2.098 1.976-2.192.373-.03.748-.057 1.123-.08M15.75 18H18a2.25 2.25 0 002.25-2.25V6.108c0-1.135-.845-2.098-1.976-2.192a48.424 48.424 0 00-1.123-.08M15.75 18.75v-1.875a3.375 3.375 0 00-3.375-3.375h-1.5a1.125 1.125 0 01-1.125-1.125v-1.5A3.375 3.375 0 006.375 7.5H5.25m11.9-3.664A2.251 2.251 0 0015 2.25h-1.5a2.251 2.251 0 00-2.15 1.586m5.8 0c.065.21.1.433.1.664v.75h-6V4.5c0-.231.035-.454.1-.664M6.75 7.5H4.875c-.621 0-1.125.504-1.125 1.125v12c0 .621.504 1.125 1.125 1.125h9.75c.621 0 1.125-.504 1.125-1.125V16.5a9 9 0 00-9-9z" />
              </svg>
              Copiar código Pix
            </>
          )}
        </button>
        {status === "waiting_payment" && (
          <p className="mt-2 text-center text-xs text-neutral-400">
            Cole o código no app do seu banco para pagar
          </p>
        )}
      </div>
    </div>
  );
}

// QR Code Generator — Byte mode, EC Level M
// Zero-dependency implementation for Pix EMV payloads
// Supports versions 1-14 (~360 byte capacity)

/* ─── GF(256) arithmetic ─── */
const EXP = new Uint8Array(512);
const LOG = new Uint8Array(256);

(() => {
  let x = 1;
  for (let i = 0; i < 255; i++) {
    EXP[i] = x;
    LOG[x] = i;
    x <<= 1;
    if (x >= 256) x ^= 0x11d;
  }
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];
})();

function gfMul(a: number, b: number): number {
  return a === 0 || b === 0 ? 0 : EXP[LOG[a] + LOG[b]];
}

/* ─── Reed-Solomon ─── */
function rsGenPoly(n: number): number[] {
  let g = [1];
  for (let i = 0; i < n; i++) {
    const next = new Array(g.length + 1).fill(0);
    for (let j = 0; j < g.length; j++) {
      next[j] ^= g[j];
      next[j + 1] ^= gfMul(g[j], EXP[i]);
    }
    g = next;
  }
  return g;
}

function rsEncode(data: number[], ecCount: number): number[] {
  const gen = rsGenPoly(ecCount);
  const fb = new Array(ecCount).fill(0);
  for (const d of data) {
    const f = d ^ fb[0];
    for (let i = 0; i < ecCount - 1; i++) fb[i] = fb[i + 1];
    fb[ecCount - 1] = 0;
    if (f !== 0) {
      for (let i = 0; i < ecCount; i++) fb[i] ^= gfMul(gen[i + 1], f);
    }
  }
  return fb;
}

/* ─── Version tables (EC Level M) ─── */
// [byteCap, ecPerBlock, g1Blocks, g1DataCW, g2Blocks, g2DataCW]
const VER: number[][] = [
  [],
  [14, 10, 1, 16, 0, 0],
  [26, 16, 1, 28, 0, 0],
  [42, 26, 1, 44, 0, 0],
  [62, 18, 2, 32, 0, 0],
  [84, 24, 2, 43, 0, 0],
  [106, 16, 4, 27, 0, 0],
  [122, 18, 4, 31, 0, 0],
  [152, 22, 2, 38, 2, 39],
  [180, 22, 3, 36, 2, 37],
  [213, 26, 4, 43, 1, 44],
  [251, 30, 1, 50, 4, 51],
  [287, 22, 6, 36, 2, 37],
  [331, 22, 8, 37, 1, 38],
  [362, 24, 4, 40, 5, 41],
];

// Alignment pattern center positions per version
const ALIGN: number[][] = [
  [], [],
  [6, 18], [6, 22], [6, 26], [6, 30], [6, 34],
  [6, 22, 38], [6, 24, 42], [6, 26, 46], [6, 28, 50],
  [6, 30, 54], [6, 32, 58], [6, 34, 62], [6, 26, 46, 66],
];

/* ─── BCH encoding ─── */
function bchFormat(data: number): number {
  let d = data << 10;
  for (let i = 14; i >= 10; i--) {
    if (d & (1 << i)) d ^= 0x537 << (i - 10);
  }
  return ((data << 10) | d) ^ 0x5412;
}

function bchVersion(ver: number): number {
  let d = ver << 12;
  for (let i = 17; i >= 12; i--) {
    if (d & (1 << i)) d ^= 0x1f25 << (i - 12);
  }
  return (ver << 12) | d;
}

/* ─── Mask patterns ─── */
type MaskFn = (r: number, c: number) => boolean;
const MASKS: MaskFn[] = [
  (r, c) => (r + c) % 2 === 0,
  (r) => r % 2 === 0,
  (_, c) => c % 3 === 0,
  (r, c) => (r + c) % 3 === 0,
  (r, c) => (((r >> 1) + Math.floor(c / 3)) & 1) === 0,
  (r, c) => ((r * c) % 2) + ((r * c) % 3) === 0,
  (r, c) => (((r * c) % 2 + (r * c) % 3) & 1) === 0,
  (r, c) => (((r + c) % 2 + (r * c) % 3) & 1) === 0,
];

/* ─── Matrix ─── */
interface QRMatrix {
  mod: boolean[][];
  fn: boolean[][];
  size: number;
}

function createMatrix(size: number): QRMatrix {
  const row = () => new Array<boolean>(size).fill(false);
  return {
    mod: Array.from({ length: size }, row),
    fn: Array.from({ length: size }, row),
    size,
  };
}

function set(m: QRMatrix, r: number, c: number, val: boolean, func: boolean) {
  if (r >= 0 && r < m.size && c >= 0 && c < m.size) {
    m.mod[r][c] = val;
    if (func) m.fn[r][c] = true;
  }
}

function placeFinder(m: QRMatrix, row: number, col: number) {
  for (let dr = -1; dr <= 7; dr++) {
    for (let dc = -1; dc <= 7; dc++) {
      const r = row + dr, c = col + dc;
      if (r < 0 || r >= m.size || c < 0 || c >= m.size) continue;
      const border = dr === -1 || dr === 7 || dc === -1 || dc === 7;
      const outer = dr === 0 || dr === 6 || dc === 0 || dc === 6;
      const inner = dr >= 2 && dr <= 4 && dc >= 2 && dc <= 4;
      set(m, r, c, outer || inner, true);
      if (border && !outer) set(m, r, c, false, true);
    }
  }
}

function placeAlignment(m: QRMatrix, row: number, col: number) {
  for (let dr = -2; dr <= 2; dr++) {
    for (let dc = -2; dc <= 2; dc++) {
      const on = Math.abs(dr) === 2 || Math.abs(dc) === 2 || (dr === 0 && dc === 0);
      set(m, row + dr, col + dc, on, true);
    }
  }
}

function placeFunctionPatterns(m: QRMatrix, version: number) {
  const s = m.size;

  placeFinder(m, 0, 0);
  placeFinder(m, 0, s - 7);
  placeFinder(m, s - 7, 0);

  for (let i = 8; i < s - 8; i++) {
    set(m, 6, i, i % 2 === 0, true);
    set(m, i, 6, i % 2 === 0, true);
  }

  const pos = ALIGN[version];
  if (pos && pos.length > 0) {
    for (const r of pos) {
      for (const c of pos) {
        if ((r < 9 && c < 9) || (r < 9 && c > s - 9) || (r > s - 9 && c < 9)) continue;
        placeAlignment(m, r, c);
      }
    }
  }

  set(m, s - 8, 8, true, true);

  for (let i = 0; i <= 8; i++) {
    set(m, 8, i, false, true);
    set(m, i, 8, false, true);
  }
  for (let i = 0; i < 8; i++) {
    set(m, 8, s - 8 + i, false, true);
    set(m, s - 7 + i, 8, false, true);
  }

  if (version >= 7) {
    for (let i = 0; i < 6; i++) {
      for (let j = 0; j < 3; j++) {
        set(m, i, s - 11 + j, false, true);
        set(m, s - 11 + j, i, false, true);
      }
    }
  }
}

function placeData(m: QRMatrix, bits: boolean[]) {
  const s = m.size;
  let idx = 0;
  let up = true;

  for (let right = s - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5;
    for (let i = 0; i < s; i++) {
      const row = up ? s - 1 - i : i;
      for (let dx = 0; dx <= 1; dx++) {
        const col = right - dx;
        if (col >= 0 && !m.fn[row][col]) {
          m.mod[row][col] = idx < bits.length && bits[idx];
          idx++;
        }
      }
    }
    up = !up;
  }
}

function applyMask(mod: boolean[][], fn: boolean[][], mask: number, size: number): boolean[][] {
  const out = mod.map((r) => [...r]);
  const f = MASKS[mask];
  for (let r = 0; r < size; r++) {
    for (let c = 0; c < size; c++) {
      if (!fn[r][c] && f(r, c)) out[r][c] = !out[r][c];
    }
  }
  return out;
}

function penalty(mod: boolean[][], size: number): number {
  let score = 0;

  for (let r = 0; r < size; r++) {
    let run = 1;
    for (let c = 1; c < size; c++) {
      if (mod[r][c] === mod[r][c - 1]) {
        run++;
        if (run === 5) score += 3;
        else if (run > 5) score++;
      } else run = 1;
    }
  }
  for (let c = 0; c < size; c++) {
    let run = 1;
    for (let r = 1; r < size; r++) {
      if (mod[r][c] === mod[r - 1][c]) {
        run++;
        if (run === 5) score += 3;
        else if (run > 5) score++;
      } else run = 1;
    }
  }

  for (let r = 0; r < size - 1; r++) {
    for (let c = 0; c < size - 1; c++) {
      const v = mod[r][c];
      if (v === mod[r][c + 1] && v === mod[r + 1][c] && v === mod[r + 1][c + 1]) score += 3;
    }
  }

  const p1 = [true, false, true, true, true, false, true, false, false, false, false];
  const p2 = [false, false, false, false, true, false, true, true, true, false, true];
  for (let r = 0; r < size; r++) {
    for (let c = 0; c <= size - 11; c++) {
      let m1 = true, m2 = true;
      for (let k = 0; k < 11; k++) {
        if (mod[r][c + k] !== p1[k]) m1 = false;
        if (mod[r][c + k] !== p2[k]) m2 = false;
      }
      if (m1 || m2) score += 40;
    }
  }
  for (let c = 0; c < size; c++) {
    for (let r = 0; r <= size - 11; r++) {
      let m1 = true, m2 = true;
      for (let k = 0; k < 11; k++) {
        if (mod[r + k][c] !== p1[k]) m1 = false;
        if (mod[r + k][c] !== p2[k]) m2 = false;
      }
      if (m1 || m2) score += 40;
    }
  }

  let dark = 0;
  for (let r = 0; r < size; r++)
    for (let c = 0; c < size; c++) if (mod[r][c]) dark++;
  const pct = (dark * 100) / (size * size);
  const lo = Math.floor(pct / 5) * 5;
  score += Math.min(Math.abs(lo - 50), Math.abs(lo + 5 - 50)) * 2;

  return score;
}

function placeFormatInfo(mod: boolean[][], size: number, mask: number) {
  const fmt = bchFormat(mask);
  const hPos = [0, 1, 2, 3, 4, 5, 7, 8];
  const vPos = [7, 5, 4, 3, 2, 1, 0];

  for (let i = 0; i < 8; i++) mod[8][hPos[i]] = ((fmt >> i) & 1) === 1;
  for (let i = 0; i < 7; i++) mod[vPos[i]][8] = ((fmt >> (8 + i)) & 1) === 1;

  for (let i = 0; i < 7; i++) mod[size - 1 - i][8] = ((fmt >> i) & 1) === 1;
  for (let i = 0; i < 8; i++) mod[8][size - 8 + i] = ((fmt >> (7 + i)) & 1) === 1;
}

function placeVersionInfo(mod: boolean[][], size: number, version: number) {
  if (version < 7) return;
  const info = bchVersion(version);
  for (let i = 0; i < 18; i++) {
    const bit = ((info >> i) & 1) === 1;
    const r = Math.floor(i / 3);
    const c = i % 3;
    mod[size - 11 + c][r] = bit;
    mod[r][size - 11 + c] = bit;
  }
}

/* ─── Public API ─── */
export interface QRResult {
  matrix: boolean[][];
  size: number;
  version: number;
}

export function generateQR(text: string): QRResult {
  const bytes = new TextEncoder().encode(text);
  const len = bytes.length;

  let version = 0;
  for (let v = 1; v < VER.length; v++) {
    if (VER[v][0] >= len) { version = v; break; }
  }
  if (!version) throw new Error(`Data too long: ${len} bytes (max ${VER[VER.length - 1][0]})`);

  const [, ecPerBlock, g1n, g1dc, g2n, g2dc] = VER[version];
  const size = 17 + 4 * version;
  const ccBits = version <= 9 ? 8 : 16;
  const totalDC = g1n * g1dc + g2n * g2dc;
  const totalBits = totalDC * 8;

  // Encode data bits
  const bits: number[] = [];
  const push = (val: number, count: number) => {
    for (let i = count - 1; i >= 0; i--) bits.push((val >> i) & 1);
  };

  push(0b0100, 4);       // byte mode
  push(len, ccBits);      // character count
  for (const b of bytes) push(b, 8);

  // terminator + padding
  const termLen = Math.min(4, totalBits - bits.length);
  push(0, termLen);
  while (bits.length % 8 !== 0) bits.push(0);

  const pads = [0xec, 0x11];
  let pi = 0;
  while (bits.length < totalBits) { push(pads[pi & 1], 8); pi++; }

  // Bits → codewords
  const codewords: number[] = [];
  for (let i = 0; i < totalDC; i++) {
    let cw = 0;
    for (let j = 0; j < 8; j++) cw = (cw << 1) | (bits[i * 8 + j] || 0);
    codewords.push(cw);
  }

  // Split into blocks → RS encode → interleave
  const blocks: number[][] = [];
  const ecBlocks: number[][] = [];
  let off = 0;

  for (let g = 0; g < g1n; g++) { blocks.push(codewords.slice(off, off + g1dc)); off += g1dc; }
  for (let g = 0; g < g2n; g++) { blocks.push(codewords.slice(off, off + g2dc)); off += g2dc; }
  for (const bl of blocks) ecBlocks.push(rsEncode(bl, ecPerBlock));

  const interleaved: number[] = [];
  const maxDC = Math.max(g1dc, g2dc || 0);
  for (let i = 0; i < maxDC; i++) {
    for (const bl of blocks) if (i < bl.length) interleaved.push(bl[i]);
  }
  for (let i = 0; i < ecPerBlock; i++) {
    for (const ec of ecBlocks) interleaved.push(ec[i]);
  }

  const dataBits: boolean[] = [];
  for (const cw of interleaved) {
    for (let i = 7; i >= 0; i--) dataBits.push(((cw >> i) & 1) === 1);
  }

  // Build matrix
  const m = createMatrix(size);
  placeFunctionPatterns(m, version);
  placeData(m, dataBits);

  // Best mask
  let bestMask = 0;
  let bestPen = Infinity;
  let bestMod: boolean[][] = m.mod;

  for (let mask = 0; mask < 8; mask++) {
    const masked = applyMask(m.mod, m.fn, mask, size);
    const p = penalty(masked, size);
    if (p < bestPen) { bestPen = p; bestMask = mask; bestMod = masked; }
  }

  placeFormatInfo(bestMod, size, bestMask);
  placeVersionInfo(bestMod, size, version);

  return { matrix: bestMod, size, version };
}
